import{d as p,C as s,o as d,c as g,a3 as t,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第十八章","description":"《正易心法》第十八章——诸卦名义，须究端的：古今失正的二十二卦，逐对纠正其名义——师比汤武、同人大有舜禹、履小畜臣道、无妄大畜君道、临观出入、谦豫止动、生命四卦、渐归妹、噬嗑贲、丰旅。","frontmatter":{"title":"正易心法·第十八章","description":"《正易心法》第十八章——诸卦名义，须究端的：古今失正的二十二卦，逐对纠正其名义——师比汤武、同人大有舜禹、履小畜臣道、无妄大畜君道、临观出入、谦豫止动、生命四卦、渐归妹、噬嗑贲、丰旅。","category":"guide","aliases":["正易心法第十八章","诸卦名义须究端的","二十二卦名义"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-18.md","filePath":"yijing/zheng-yi-xin-fa/chapter-18.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-18.md"},x=p({...c,setup(u){const i=[{id:"z18-01",label:"一、名义须究端的",showLabel:!0,sentences:[["诸卦名义，须究",{text:"端的",glossary:"duandi"},"。名义不正，《易》道",{text:"悬绝",glossary:"xuanjue"},"。"]],note:["各卦的名称与含义，必须追究到准确无误。名义不正确，《易》道就悬空断绝了。（「悬绝」＝悬空而没有落脚点、断绝而无法贯通。**这就是「落处」的反面**：名义正，则根扎入土；名义不正，则根悬于空。）"]},{id:"z18-02",label:"二、古今失正二十余卦",showLabel:!0,sentences:[["《易》卦名义，古今失其正者，二十余卦：师、比、小畜、履、同人、大有、谦、豫、临、观、噬嗑、贲、无妄、大畜、颐、大过、渐、归妹、丰、旅、中孚、小过是也。"]],note:["《易》卦的名义，古今失去正确理解的，有二十余卦：师、比、小畜、履、同人、大有、谦、豫、临、观、噬嗑、贲、无妄、大畜、颐、大过、渐、归妹、丰、旅、中孚、小过。（**恰好是十一对反对卦**——麻衣把它们成对列出，正是第十七章「名义无不反对」的具体验证。）"]},{id:"z18-03",label:"三、创业与嗣位",showLabel:!0,sentences:[["盖师以正众，比以兴王，二卦以武功创业，",{text:"汤武",glossary:"tangwu"},"之卦也。同人穷而在下，大有达而在上，二卦以文德嗣位，",{text:"舜禹",glossary:"shunyu"},"之卦也。"]],note:["师以整治众人，比以兴起王业——两卦以武功创业，是商汤、周武王的卦。同人处穷困在下，大有处通达在上——两卦以文德继承帝位，是舜、禹的卦。（**这两个历史原型不是随意比附，而是卦画结构的印证**：师☷☵一阳统众阴＝将帅统兵；比☷☵一阳居众阴之上＝众人归附；同人☰☲离在下＝文明之人处于下位；大有☲☰离在上＝文明之德居于上位。）"]},{id:"z18-04",label:"四、臣道与君道",showLabel:!0,sentences:[["履以阴德而蹈艰危，以致小畜之安富；人臣之事也。无妄以阴德而践",{text:"灾眚",glossary:"zaisheng"},"，以致大畜之喜庆，人君之事也。"]],note:["履以阴柔之德踩踏艰险危难，从而达到小畜的安富——这是人臣的处世之道。无妄以阴柔之德经历灾难祸患，从而达到大畜的喜庆——这是人君的处世之道。（两组的路径相同：**以阴德处难，终得回报**；差别在规模：臣子得「小成」（小畜），君主得「大成」（大畜）。）"]},{id:"z18-05",label:"五、出入与止动",showLabel:!0,sentences:[["临以阳来，宜出而有为；观以阴生，宜入而无为。谦则止在象后而存义，豫则动在象前而",{text:"知几",glossary:"zhiji"},"。"]],note:["临以阳气来临，宜于出外有所作为；观以阴气生长，宜于退入无所作为。谦是止步在卦象之后而保存义理；豫是行动在卦象之前而知晓先机。（临、观都是十二消息卦：**临（二阳在下）宜出，观（二阳在上、阴渐盛）宜入**——知时而动。谦、豫则是一止一动：谦（艮止在下）止而后存义，豫（震动在先）动而先知几。）"]},{id:"z18-06",label:"六、生命与婚配",showLabel:!0,sentences:[["中孚则始生，小过则夭折。颐则成人而养生，大过则寿终而丧死。渐以正而进，归妹以说而合。"]],note:["中孚象征生命开始，小过象征生命夭折；颐象征成人之后的养生，大过象征寿终正寝而死亡。渐以正道循序渐进，归妹以喜悦而结合。（**生命四卦正是第十六章所说的「对体卦」**：中孚（始生）、小过（夭折）、颐（养生）、大过（丧死）——四个生命的关键节点，正是「死生寿夭造化之枢机」的具体内容。渐与归妹则是一正一悦：正式的婚配 vs 悦而结合。）"]},{id:"z18-07",label:"七、德命之别与谛观",showLabel:!0,sentences:[["噬嗑以贪而致罪，贲以义而致饰。丰则得所归而富盛，旅则失所基而困穷。凡此二十余卦，其名义显然，见于卦画反对，有不可掩者如此，当",{text:"谛观",glossary:"diguan"},"之也。《大传》曰：“天下之动，贞夫一者也。”苟名义不当，则一卦无所",{text:"归宿",glossary:"guisu"},"也，故曰：《易》道悬绝也。"]],note:["噬嗑以贪婪而导致罪过，贲以义理而导致文饰；丰是得到归宿而富足盛大，旅是失去根基而困顿穷乏。这二十余卦，其名义显然见于卦画反对，有不可掩盖的道理，应当仔细观察。《大传》说「天下的变动，以正为准则」；如果名义不正确，则一卦就无所归宿了，所以说：《易》道悬绝。（**「归宿」是本章的关键词**——名义正，则每卦有明确的落处；名义不正，则「一卦无所归宿」。这与第一章的「落处」是同一件事，只是换了一个说法。）"]}],o=[{id:"duandi",term:"端的",pinyin:"duān dì",meaning:"确切的、正确的。究端的：追究到准确无误。"},{id:"xuanjue",term:"悬绝",pinyin:"xuán jué",meaning:"悬空断绝。悬＝没有落脚点，绝＝无法贯通。名义不正的后果。"},{id:"tangwu",term:"汤武",pinyin:"tāng wǔ",meaning:"商汤、周武王。以武功创业的历史原型，对应师、比二卦。"},{id:"shunyu",term:"舜禹",pinyin:"shùn yǔ",meaning:"舜、禹。以文德禅让继位的历史原型，对应同人、大有二卦。"},{id:"zaisheng",term:"灾眚",pinyin:"zāi shěng",meaning:"灾难祸患。眚是过失、灾祸。"},{id:"zhiji",term:"知几",pinyin:"zhī jī",meaning:"知晓机兆。几是事物变化的微妙先兆。豫卦动在象前，故能知几。"},{id:"diguan",term:"谛观",pinyin:"dì guān",meaning:"仔细观察。谛是仔细、审慎。"},{id:"guisu",term:"归宿",pinyin:"guī sù",meaning:"最终的归属。名义正，则一卦有归宿；名义不正，则无所归宿。"}];return(b,n)=>{const r=s("DaoTextReading"),l=s("DaoKeywordCards");return d(),g("div",null,[n[0]||(n[0]=t(`<h1 id="正易心法·第十八章" tabindex="-1">正易心法·第十八章 <a class="header-anchor" href="#正易心法·第十八章" aria-label="Permalink to &quot;正易心法·第十八章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章是第十七章「名义无不反对」的<strong>完整展开与验证</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第十七章（原则）：六十四卦皆有取象；名义无不反对；不知此为「大病」</span></span>
<span class="line"><span>第十八章（验证）：列出二十二个具体案例，逐一说明每对卦的正确名义</span></span>
<span class="line"><span>               指出古今失其正的具体卦目</span></span></code></pre></div><p><strong>核心贡献</strong>：不只是说「名义应该反对」，而是给出了二十二卦的正确名义——<strong>这是对《易》学的具体纠正。</strong></p><p><strong>二十二卦的主题分层</strong>：</p><table tabindex="0"><thead><tr><th>层次</th><th>卦对</th><th>主题</th></tr></thead><tbody><tr><td>政治层</td><td>师比、同人大有</td><td>创业与治国</td></tr><tr><td>处世层</td><td>履小畜、无妄大畜</td><td>臣道与君道</td></tr><tr><td>时机层</td><td>临观、谦豫</td><td>知时而动</td></tr><tr><td>生命层</td><td>中孚小过、颐大过</td><td>生命周期</td></tr><tr><td>人伦层</td><td>渐归妹</td><td>男女婚配</td></tr><tr><td>道德层</td><td>噬嗑贲</td><td>品德修养</td></tr><tr><td>命运层</td><td>丰旅</td><td>命运起伏</td></tr></tbody></table><p><strong>七个层次，涵盖人生的全部面向。</strong></p><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>为什么是「古今失其正」？</strong>——这是一个大胆的批评：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>不只是批评汉儒，而是说从古到今都理解错了</span></span>
<span class="line"><span></span></span>
<span class="line"><span>失正的原因：</span></span>
<span class="line"><span>  1. 只看卦辞，不看卦画 → 不知取象，不知反对</span></span>
<span class="line"><span>  2. 孤立理解每卦 → 不知每卦必须在反对关系中理解</span></span>
<span class="line"><span>  3. 不知卦的历史原型 → 不知师比是汤武之卦</span></span></code></pre></div><p><strong>历史原型的方法论意义</strong>——本章新增了一个方法：<strong>以历史原型验证卦义</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>师卦（一阳统众阴）：</span></span>
<span class="line"><span>  卦画 = 将帅统兵</span></span>
<span class="line"><span>  义理 = 正众（整治军纪）</span></span>
<span class="line"><span>  历史 = 商汤整军伐桀</span></span>
<span class="line"><span></span></span>
<span class="line"><span>比卦（一阳居众阴上）：</span></span>
<span class="line"><span>  卦画 = 众人归附一阳</span></span>
<span class="line"><span>  义理 = 兴王（众归王者）</span></span>
<span class="line"><span>  历史 = 众诸侯归附</span></span>
<span class="line"><span></span></span>
<span class="line"><span>三个层次相互印证：卦画 ↔ 义理 ↔ 历史</span></span></code></pre></div><p><strong>生命四卦与第十六章的呼应</strong>：</p><table tabindex="0"><thead><tr><th>卦</th><th>名义</th><th>生命节点</th></tr></thead><tbody><tr><td>中孚</td><td>始生</td><td>生命开始（孚＝孵化）</td></tr><tr><td>小过</td><td>夭折</td><td>生命未及成长即夭折</td></tr><tr><td>颐</td><td>养生</td><td>成人后的维持与养育</td></tr><tr><td>大过</td><td>丧死</td><td>生命到达终点</td></tr></tbody></table><p><strong>这四卦正是第十六章所说的「对体卦」</strong>——<strong>它们的名义正好对应生命的四个关键节点：始生、夭折、养生、丧死。</strong> 「其体不变」的深层含义是：<strong>不管时代如何变化，生命总有这四个节点，永远不变。</strong></p><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先把二十二卦按十一对读一遍，<strong>体会「反对」两个字</strong>；</li><li>再看「汤武／舜禹」两组——<strong>这是本章最有画面感的部分</strong>；</li><li>记住最后一句：<strong>「苟名义不当，则一卦无所归宿」——归宿，就是落处。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>须究端的</strong>：名义必须准确，否则《易》道悬绝。</li><li><strong>二十二卦失正</strong>：古今对它们理解有误。</li><li><strong>汤武之卦</strong>：师比，武功创业。</li><li><strong>舜禹之卦</strong>：同人大有，文德嗣位。</li><li><strong>臣道君道</strong>：履小畜（小成）、无妄大畜（大成）。</li><li><strong>出入止动</strong>：临观知时，谦豫知几。</li><li><strong>生命四卦</strong>：中孚小过、颐大过。</li><li><strong>归宿</strong>：名义正，则一卦有落处。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,21)),e(r,{colophon:"须究端的 · 二十二卦 · 汤武舜禹 · 名义归宿",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第十八章原文",sections:i,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本，不作统一。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(l,{items:[{term:"须究端的",pinyin:["jiū","duān"],meaning:"卦名与含义必须追究到准确无误——名义不正确，《易》道就悬空断绝。"},{term:"汤武之卦",pinyin:["tāng","wǔ"],meaning:"师（正众）与比（兴王）以武功创业，是商汤、周武王的卦。卦画：师＝一阳统众阴，比＝一阳居众阴上。"},{term:"舜禹之卦",pinyin:["shùn","yǔ"],meaning:"同人（穷而在下）与大有（达而在上）以文德嗣位，是舜、禹的卦。"},{term:"臣道 · 君道",pinyin:["chén","dào"],meaning:"履→小畜（阴德蹈艰致安富）为臣道；无妄→大畜（阴德践灾致喜庆）为君道。规模不同，路径相同。"},{term:"生命四卦",pinyin:["shēng","mìng"],meaning:"中孚（始生）、小过（夭折）、颐（养生）、大过（丧死）——四卦皆为对体卦，正是「死生寿夭造化之枢机」。"},{term:"归宿",pinyin:["guī","sù"],meaning:"名义正，则一卦有明确的落处（归宿）；名义不当，则一卦无所归宿，故曰「《易》道悬绝」。"}]}),n[3]||(n[3]=t(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章是第十七章「名义无不反对」的完整展开与验证：<strong>列出二十二卦，逐对说明其正确名义</strong>，并指出古今失正的卦目。</p><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>为什么是「古今失其正」？</strong>——这不只是批评汉儒，而是说<strong>从古到今都理解错了</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>失正的原因：</span></span>
<span class="line"><span>  1. 只看卦辞，不看卦画 → 不知取象，不知反对</span></span>
<span class="line"><span>  2. 孤立理解每卦 → 不知每卦必须在反对关系中理解</span></span>
<span class="line"><span>  3. 不知卦的历史原型</span></span></code></pre></div><p><strong>历史原型的方法论意义</strong>——本章新增的方法：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>师卦（一阳统众阴）→ 卦画＝将帅统兵 → 义理＝正众 → 历史＝汤武整军</span></span>
<span class="line"><span>比卦（一阳居众阴上）→ 卦画＝众归一阳 → 义理＝兴王 → 历史＝诸侯来归</span></span>
<span class="line"><span></span></span>
<span class="line"><span>三个层次相互印证：卦画 ↔ 义理 ↔ 历史</span></span></code></pre></div><p><strong>生命四卦与第十六章的呼应</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第十六章说：颐、大过、中孚、小过是「对体卦」，是「死生寿夭造化之枢机」</span></span>
<span class="line"><span>第十八章说：中孚＝始生，小过＝夭折，颐＝养生，大过＝丧死</span></span>
<span class="line"><span></span></span>
<span class="line"><span>为什么它们是「对体卦」（翻转不变）？</span></span>
<span class="line"><span>  因为生命的这四个节点是宇宙的稳定结构：</span></span>
<span class="line"><span>  不管时代如何变化，生命总有始生、夭折、养生、丧死</span></span>
<span class="line"><span>  = 「其体不变」的深层含义</span></span></code></pre></div><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>把二十二卦按十一对读一遍，<strong>体会「反对」两个字</strong>；</li><li>读「汤武／舜禹」两组时，<strong>试着把卦画、义理、历史三层串起来</strong>；</li><li>记住最后一句作为全章的心法：<strong>「苟名义不当，则一卦无所归宿」——归宿，就是落处。</strong></li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>各卦的名称与含义，必须追究到准确无误。名义不正确，《易》道就悬空断绝了。</p><p>《易》卦的名义，古今失去正确理解的有二十余卦：师、比、小畜、履、同人、大有、谦、豫、临、观、噬嗑、贲、无妄、大畜、颐、大过、渐、归妹、丰、旅、中孚、小过。</p><p>师以整治众人，比以兴起王业——两卦以武功创业，是商汤、周武王的卦。同人处穷困在下，大有处通达在上——两卦以文德继承帝位，是舜、禹的卦。</p><p>履以阴柔之德踩踏艰危，从而达到小畜的安富——这是人臣之道。无妄以阴柔之德经历灾难，从而达到大畜的喜庆——这是人君之道。</p><p>临以阳气来临，宜于出外有为；观以阴气生长，宜于退入无为。谦是止步在卦象之后保存义理，豫是行动在卦象之前知晓先机。</p><p>中孚象征生命开始，小过象征生命夭折；颐象征成人之后的养生，大过象征寿终正寝而死亡。渐以正道循序渐进，归妹以喜悦而结合。</p><p>噬嗑以贪婪导致罪过，贲以义理导致文饰；丰是得到归宿而富足盛大，旅是失去根基而困顿穷乏。这二十余卦的名义显然见于卦画反对，有不可掩盖的道理，应当仔细观察。《大传》说「天下的变动，以正为准则」；如果名义不正确，则一卦就无所归宿了，所以说：《易》道悬绝。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第十八章把第十七章的「大病」诊断，开成了一张具体的处方——<strong>二十二个卦名，一个个对回来；麻衣不改卦画，只改读法。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「须究端的」</strong>——<strong>「端的」是宋人口语，意思是「到底、究竟」。</strong> 麻衣要的不是「大致说得通」，是「一点不错」。<strong>这种严格，正来自他的核心信念：名义不正，卦就「无所归宿」。</strong></li><li><strong>「汤武／舜禹」两组</strong>——这是本章最有画面感的部分。<strong>师比是武功创业（打天下），同人大有是文德嗣位（坐天下）。</strong> 麻衣把卦画、义理、历史三层串成一条线：<strong>一阳统众阴是「师」，一阳在众阴之上是「比」——同一根阳爻，位置一变，含义全变。</strong></li><li><strong>「履→小畜」与「无妄→大畜」</strong>——这个对照我很喜欢：<strong>臣子得「小成」，君主得「大成」；路径一样（以阴德处难），规模不同。</strong> 这不是道德训诫，是<strong>位置决定容量</strong>。</li><li><strong>「中孚始生／小过夭折／颐养生／大过丧死」</strong>——四卦正好是生命的四个节点。<strong>第十六章说它们是「对体卦」（翻转不变），本章给出了为什么：因为生命的这四个节点，从古到今都没有变过。</strong></li><li><strong>「归宿」</strong>——最后落在这两个字上。<strong>名义正，则卦有归宿；名义不正，则卦悬空。</strong> 这与第一章的「落处」是同一件事——<strong>只是换了一个更宋人的说法：落处，就是归宿。</strong></li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：<strong>中孚像蛋、小过像飞鸟；蛋孵化为鸟，为何小过却是「夭折」而不是「飞翔」？</strong> 我的想法：<strong>小过的卦辞是「飞鸟遗之音，不宜上，宜下」——「遗音」二字极妙：只听得到声音，抬头时鸟已不见了。</strong> 飞翔是<strong>还在</strong>，遗音是<strong>已过</strong>。<strong>所以小过不是「自由」，是「过度之后只剩余响」</strong>——鸟飞得太高太远，超出了它该在的位置，于是只剩下一点回音。<strong>这就是「小者过也」的含义：过了，就回不来。</strong> 而中孚是蛋——<strong>蛋里的鸟还没出来，所以还有全然的可能</strong>；小过是鸟已飞远，只剩声音。<strong>一在未生，一在已过，正好把「生」的两头夹住。</strong></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-01">第一章 · 羲皇易道</a> — 「落处」（本章以「归宿」重述）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-16">第十六章 · 卦有反对</a> — 对体八卦是造化枢机（本章给出生命四卦的名义）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-17">第十七章 · 皆有取象</a> — 名义无不反对（本章是逐个验证）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-23">第二十三章</a> — 卦序与八体的文献纠正（本章是名义纠正）</li><li><a href="/Dao/yijing/shi-yi/za-gua-zhuan">杂卦传</a> — 「比乐师忧」等对比，正是本章所本</li></ul>`,26))])}}});export{y as __pageData,x as default};
